FROM daily

    delete_flag = 0

        AND content LIKE CONCAT('%', #{content}, '%')


        AND type = #{type}


        AND is_top = #{isTop}


        AND status = #{status}


        AND create_time >= #{begin}


        AND create_time <= #{end}


ORDER BY is_top DESC, publish_time DESC, create_time DESC

