mapper.update:
UPDATE daily
SET is_top = #{isTop},
    update_time = #{updateTime}
WHERE id = #{id}

UPDATE daily
SET status = #{status},
    timed_publish_time = #{timedPublishTime},
    update_time = #{updateTime}
WHERE id = #{id}

UPDATE daily
SET status = #{status},
    timed_publish_time = NULL,
    update_time = #{updateTime}
WHERE id = #{id}

